import os
from typing import Optional

from openai import AzureOpenAI


class AzureModelResolverError(Exception):
    pass


def _get_env(name: str, required: bool = True) -> Optional[str]:
    value = os.getenv(name)
    if required and not value:
        raise AzureModelResolverError(f"Missing required environment variable: {name}")
    return value


def _normalize_endpoint(endpoint: str) -> str:
    return endpoint.rstrip("/")


def resolve_azure_openai_deployment(
    client: AzureOpenAI,
    *,
    model_name: str,
) -> str:
    target = model_name.strip().lower()
    deployments = client.deployments.list()

    for deployment in deployments.data:
        deployed_model = (
            getattr(deployment, "model", None)
            or getattr(deployment, "model_name", None)
            or getattr(deployment, "model_id", None)
        )
        deployment_name = (
            getattr(deployment, "id", None)
            or getattr(deployment, "name", None)
        )

        if deployed_model and deployment_name and str(deployed_model).strip().lower() == target:
            return str(deployment_name)

    available = []
    for deployment in deployments.data:
        deployment_name = (
            getattr(deployment, "id", None)
            or getattr(deployment, "name", None)
        )
        deployed_model = (
            getattr(deployment, "model", None)
            or getattr(deployment, "model_name", None)
            or getattr(deployment, "model_id", None)
        )
        available.append(
            {
                "deployment": deployment_name,
                "model": deployed_model,
            }
        )

    raise AzureModelResolverError(
        f"No Azure OpenAI deployment found for model '{model_name}'. "
        f"Available deployments: {available}"
    )


def invoke_resolved_azure_openai_chat(
    prompt: str,
    *,
    model_name: str = "gpt-4o-mini",
    api_version: Optional[str] = None,
    temperature: float = 0.2,
    max_tokens: int = 300,
) -> str:
    endpoint = _normalize_endpoint(_get_env("AZURE_OPENAI_ENDPOINT"))
    api_key = _get_env("AZURE_OPENAI_API_KEY")
    api_version = api_version or os.getenv("AZURE_OPENAI_API_VERSION", "2024-10-21")

    client = AzureOpenAI(
        azure_endpoint=endpoint,
        api_key=api_key,
        api_version=api_version,
    )

    deployment_name = resolve_azure_openai_deployment(
        client,
        model_name=model_name,
    )

    response = client.chat.completions.create(
        model=deployment_name,
        messages=[
            {"role": "system", "content": "You are a helpful assistant."},
            {"role": "user", "content": prompt},
        ],
        temperature=temperature,
        max_tokens=max_tokens,
    )

    if not response.choices:
        raise AzureModelResolverError("Azure OpenAI returned no choices.")

    message = response.choices[0].message
    content = getattr(message, "content", None)

    if isinstance(content, str):
        return content

    if isinstance(content, list):
        parts = []
        for item in content:
            text = getattr(item, "text", None)
            if text:
                parts.append(text)
            elif isinstance(item, dict) and item.get("text"):
                parts.append(item["text"])
        if parts:
            return "".join(parts)

    raise AzureModelResolverError("Azure OpenAI returned an unexpected response format.")
